import React, { useState, useRef, useEffect } from 'react';
import { Link } from 'react-router-dom';
import './History.css';

/* ──────────────────────────────────────────────────────────
   SEASON DATA — single source of truth
────────────────────────────────────────────────────────── */

const SEASONS = [
  {
    id:   'decode',
    year: '2026',
    game: 'Decode',
    tag:  'current',          // drives the pill badge
    label: 'Decode — 2026',
    type: 'upcoming',
    sub:  'East Bay League · Dublin, CA · FTC Division',
    intro:
      'We are preparing for our first official matches of the Decode season — our current campaign. ' +
      'Hardware is in development, software is being refined, and the team is building on everything ' +
      'learned in our rookie year to compete at a higher level than ever before.',
    events: [
      {
        id:     'decode-meet-1',
        name:   'East Bay League — Meet 1',
        date:   'Fall 2026',
        status: 'upcoming',
        detail:
          'Our first official match of the Decode season. Mechanical prototyping and ' +
          'NextFTC autonomous routines are underway as we adapt to the new game challenge.',
      },
      {
        id:     'decode-meet-2',
        name:   'East Bay League — Meet 2',
        date:   'Winter 2026',
        status: 'upcoming',
        detail:
          'Building on Meet 1 field data, we plan to deploy fully refined autonomous ' +
          'routines and competition-hardened scoring mechanisms.',
      },
      {
        id:     'decode-tournament',
        name:   'East Bay League Tournament',
        date:   'Early 2027',
        status: 'upcoming',
        detail:
          'Our second League Tournament — the first chance to defend the standard we ' +
          'set as rookies and push for a new award podium.',
      },
    ],
  },
  {
    id:   'biobuzz',
    year: '2026',
    game: 'BIOBUZZ',
    tag:  'upcoming',         // drives the pill badge
    label: 'BIOBUZZ — 2026',
    type: 'upcoming',
    sub:  'East Bay League · Dublin, CA · FTC Division',
    intro:
      'We are preparing for our first official matches of the BIOBUZZ season. ' +
      'Hardware is in development, software is being refined, and the team is ready ' +
      'to compete at a higher level than ever before.',
    events: [
      {
        id:     'biobuzz-meet-1',
        name:   'East Bay League — Meet 1',
        date:   'Fall 2025',
        status: 'upcoming',
        detail:
          'Our first official match of the BIOBUZZ season. Hardware and software ' +
          'development is underway as we adapt to the new game challenge.',
      },
      {
        id:     'biobuzz-meet-2',
        name:   'East Bay League — Meet 2',
        date:   'Winter 2025',
        status: 'upcoming',
        detail:
          'Building on Meet 1 data, we plan to deploy fully refined autonomous routines ' +
          'and competition-hardened scoring mechanisms.',
      },
      {
        id:     'biobuzz-tournament',
        name:   'East Bay League Tournament',
        date:   'Early 2026',
        status: 'upcoming',
        detail:
          'Our second appearance at the League Tournament — and our first chance to ' +
          'defend the standard we set in our rookie year.',
      },
    ],
  },
  {
    id:   'rookie-2025',
    year: '2025',
    game: 'Rookie Season',
    tag:  null,               // no special badge
    label: 'Rookie Season — 2025',
    type: 'completed',
    sub:  'East Bay League · Dublin, CA · FTC Division',
    intro:
      'Our debut year in the FIRST Tech Challenge. We competed across three East Bay ' +
      'League meets, refined our robot and strategy with each outing, and capped the ' +
      'season with a Connect Award at the East Bay League Tournament.',
    award: {
      icon:  '🏆',
      name:  'Connect Award',
      event: 'East Bay League Tournament',
      desc:
        'The FIRST Tech Challenge Connect Award recognizes teams that best exemplify the ' +
        'FIRST mission — inspiring others to pursue STEM through advocacy, partnerships, and ' +
        'outreach. Winning this in our rookie season reflects our commitment to community ' +
        'impact, from founding BASE Robotics to hosting free workshops across the Tri-Valley.',
      stats: [
        { val: '2',    label: 'Nonprofits Founded / Joined' },
        { val: '100+', label: 'Students Reached' },
        { val: '4',    label: 'FTC Teams Assisted' },
      ],
    },
    events: [
      {
        id:        'meet-1',
        name:      'East Bay League — Meet 1',
        date:      'Oct 2024',
        venue:     'East Bay Region, CA',
        result:    'Participated',
        badge:     'rookie',
        highlight: false,
        detail:
          'Our debut competitive appearance. We took the field for the first time, ' +
          'stress-tested our autonomous routines in a live match environment, and ' +
          'gathered critical performance data.',
      },
      {
        id:        'meet-2',
        name:      'East Bay League — Meet 2',
        date:      'Nov 2024',
        venue:     'East Bay Region, CA',
        result:    'Participated',
        badge:     'progress',
        highlight: false,
        detail:
          'Armed with match footage and field data from Meet 1, we returned with ' +
          'hardware and software refinements — improving our autonomous cycle count ' +
          'and tightening driver coordination.',
      },
      {
        id:        'meet-3',
        name:      'East Bay League — Meet 3',
        date:      'Dec 2024',
        venue:     'East Bay Region, CA',
        result:    'Participated',
        badge:     'progress',
        highlight: false,
        detail:
          'Our most polished regular-season performance. Autonomous reliability reached ' +
          'a new high-water mark and alliance strategies showed measurable improvement ' +
          'heading into the tournament.',
      },
      {
        id:        'tournament',
        name:      'East Bay League Tournament',
        date:      'Jan 2025',
        venue:     'East Bay Region, CA',
        result:    '🏆 Connect Award',
        badge:     'award',
        highlight: true,
        detail:
          'The culmination of our rookie season. We competed in the full League ' +
          'Tournament bracket and were honored with the Connect Award — recognizing ' +
          'our exceptional outreach, community partnerships, and commitment to the ' +
          'FIRST mission.',
      },
    ],
  },
];

/* ──────────────────────────────────────────────────────────
   SEASON TAG PILL
────────────────────────────────────────────────────────── */
function SeasonPill({ tag }) {
  if (!tag) return null;
  return (
    <span className={`season-pill season-pill--${tag}`}>
      {tag === 'current'  ? 'Current Season'  : 'Upcoming Season'}
    </span>
  );
}

/* ──────────────────────────────────────────────────────────
   CUSTOM DROPDOWN
────────────────────────────────────────────────────────── */
function SeasonDropdown({ seasons, selected, onSelect }) {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);

  /* Close on outside click */
  useEffect(() => {
    const handler = (e) => {
      if (ref.current && !ref.current.contains(e.target)) setOpen(false);
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  /* Close on Escape */
  useEffect(() => {
    const handler = (e) => { if (e.key === 'Escape') setOpen(false); };
    document.addEventListener('keydown', handler);
    return () => document.removeEventListener('keydown', handler);
  }, []);

  const current = seasons.find((s) => s.id === selected);

  return (
    <div
      className={`season-dropdown ${open ? 'season-dropdown--open' : ''}`}
      ref={ref}
    >
      {/* Trigger button */}
      <button
        id="season-dropdown-trigger"
        className="season-dropdown__trigger"
        onClick={() => setOpen((o) => !o)}
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-label="Select competition season"
      >
        <span className="season-dropdown__trigger-left">
          <span className="season-dropdown__trigger-label">Season</span>
          <span className="season-dropdown__trigger-value">
            {current?.label}
            {current?.tag && <SeasonPill tag={current.tag} />}
          </span>
        </span>
        <span className="season-dropdown__chevron" aria-hidden="true">
          {open ? '▲' : '▼'}
        </span>
      </button>

      {/* Options panel */}
      <ul
        className="season-dropdown__menu"
        role="listbox"
        aria-label="Competition seasons"
      >
        {seasons.map((season) => (
          <li
            key={season.id}
            role="option"
            aria-selected={season.id === selected}
            className={`season-dropdown__option ${season.id === selected ? 'season-dropdown__option--active' : ''}`}
            onClick={() => { onSelect(season.id); setOpen(false); }}
            id={`season-option-${season.id}`}
          >
            <span className="season-dropdown__option-meta">
              <span className="season-dropdown__option-game">{season.label}</span>
              {season.tag && <SeasonPill tag={season.tag} />}
            </span>
            {season.type === 'completed' && (
              <span className="season-dropdown__option-badge">Completed</span>
            )}
            {season.id === selected && (
              <span className="season-dropdown__check" aria-hidden="true">✓</span>
            )}
          </li>
        ))}
      </ul>
    </div>
  );
}

/* ──────────────────────────────────────────────────────────
   COMPLETED SEASON PANEL — timeline + award block
────────────────────────────────────────────────────────── */
function CompletedSeason({ season }) {
  return (
    <div className="season-panel season-panel--completed" key={season.id}>
      {/* Award callout header */}
      {season.award && (
        <div className="season__award-callout" aria-label="Season award">
          <span className="season__award-icon" aria-hidden="true">{season.award.icon}</span>
          <div>
            <span className="season__award-name">{season.award.name}</span>
            <span className="season__award-event label-tag">{season.award.event}</span>
          </div>
        </div>
      )}

      {/* Timeline */}
      <div
        className="season__timeline"
        role="list"
        aria-label={`${season.game} season events`}
      >
        {season.events.map((event, i) => (
          <div key={event.id} className="season__timeline-item" role="listitem">
            <div className="season__timeline-marker" aria-hidden="true">
              <div
                className={`season__timeline-dot ${
                  event.highlight ? 'season__timeline-dot--award' : ''
                }`}
              />
              {i < season.events.length - 1 && (
                <div className="season__timeline-line" />
              )}
            </div>
            <EventCard event={event} index={i} />
          </div>
        ))}
      </div>

      {/* Connect Award feature block */}
      {season.award && (
        <div className="connect-award" id="connect-award" aria-label="Award detail">
          <div className="connect-award__icon" aria-hidden="true">{season.award.icon}</div>
          <div className="connect-award__body">
            <p className="label-tag connect-award__tag">Highest Achievement — {season.game}</p>
            <h3 className="headline headline-md connect-award__title">
              {season.award.name} <span className="text-yellow">Winner</span>
            </h3>
            <p className="connect-award__desc">{season.award.desc}</p>
            <div className="connect-award__stats">
              {season.award.stats.map(({ val, label }) => (
                <div key={label} className="connect-award__stat">
                  <span className="connect-award__stat-val">{val}</span>
                  <span className="connect-award__stat-label">{label}</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

/* ──────────────────────────────────────────────────────────
   UPCOMING SEASON PANEL — event cards grid
────────────────────────────────────────────────────────── */
function UpcomingSeason({ season }) {
  return (
    <div className="season-panel season-panel--upcoming" key={season.id}>
      <div className="upcoming-grid">
        {season.events.map((event, i) => (
          <UpcomingCard key={event.id} event={event} index={i} />
        ))}
      </div>
      <div className="upcoming-cta">
        <p className="text-muted">
          Check back after events conclude for results and recaps.
        </p>
        <Link to="/" className="btn btn-outline" id="history-cta-home">
          ← Back to Home
        </Link>
      </div>
    </div>
  );
}

/* ──────────────────────────────────────────────────────────
   CARD SUB-COMPONENTS
────────────────────────────────────────────────────────── */
function EventCard({ event, index }) {
  return (
    <div
      id={event.id}
      className={`event-card card animate-fadeInUp delay-${(index % 5) + 1} ${
        event.highlight ? 'event-card--highlight' : ''
      }`}
    >
      {event.highlight && (
        <div className="event-card__award-ribbon" aria-hidden="true">
          <span>★ AWARD</span>
        </div>
      )}
      <div className="event-card__top">
        <div className="event-card__meta">
          <span className={`event-card__badge event-card__badge--${event.badge}`}>
            {event.badge === 'award'
              ? '🏆 Award'
              : event.badge === 'rookie'
              ? 'Debut'
              : 'Event'}
          </span>
          <span className="event-card__date label-tag">{event.date}</span>
        </div>
        <h3 className="headline headline-sm event-card__name">{event.name}</h3>
        <p className="event-card__venue text-muted">
          <span aria-hidden="true">📍 </span>{event.venue}
        </p>
      </div>
      <p className="event-card__detail">{event.detail}</p>
      <div className="event-card__result">
        <span className="event-card__result-val">{event.result}</span>
      </div>
    </div>
  );
}

function UpcomingCard({ event, index }) {
  return (
    <div
      id={event.id}
      className={`upcoming-card animate-fadeInUp delay-${(index % 3) + 1}`}
    >
      <div className="upcoming-card__date-badge">{event.date}</div>
      <h3 className="headline headline-sm upcoming-card__name">{event.name}</h3>
      <p className="upcoming-card__detail text-muted">{event.detail}</p>
      <div className="upcoming-card__status">
        <span className="upcoming-card__status-dot" aria-hidden="true" />
        Preparing
      </div>
    </div>
  );
}

/* ──────────────────────────────────────────────────────────
   PAGE EXPORT
────────────────────────────────────────────────────────── */
export default function History() {
  const [selectedId, setSelectedId] = useState('decode');
  const activeSeason = SEASONS.find((s) => s.id === selectedId);

  return (
    <main className="page" id="history-page">

      {/* ── Page Hero ── */}
      <section className="history-hero" aria-labelledby="history-heading">
        <div className="history-hero__bg"   aria-hidden="true" />
        <div className="history-hero__grid" aria-hidden="true" />
        <div className="history-hero__glow" aria-hidden="true" />

        <div className="container history-hero__content">
          <div className="section-label">
            <span className="label-tag">30473 / Season Record</span>
          </div>
          <h1
            id="history-heading"
            className="headline headline-lg history-hero__title"
          >
            Competition <span className="text-yellow">History</span>
          </h1>
          <p className="history-hero__sub text-muted">
            Every match. Every award. Every lesson learned on the field.
            This is how Team Duck 30473 earns its stripes.
          </p>

          {/* Career highlights strip */}
          <div className="history-hero__highlights">
            {[
              { val: '1',      key: 'Award Won' },
              { val: '4',      key: 'Meets Competed' },
              { val: '2025',   key: 'Rookie Year' },
              { val: 'Decode', key: 'Current Season', yellow: true },
            ].map(({ val, key, yellow }) => (
              <React.Fragment key={key}>
                <div className="history-hero__highlight">
                  <span className={`history-hero__highlight-val${yellow ? ' text-yellow' : ''}`}>
                    {val}
                  </span>
                  <span className="history-hero__highlight-key">{key}</span>
                </div>
                {key !== 'Current Season' && (
                  <div className="history-hero__highlight-divider" aria-hidden="true" />
                )}
              </React.Fragment>
            ))}
          </div>
        </div>
        <div className="history-hero__cut" aria-hidden="true" />
      </section>

      {/* ── Season Browser ── */}
      <section
        className="history-browser section"
        aria-label="Season browser"
      >
        <div className="container">

          {/* ── Dropdown + Season Header ── */}
          <div className="browser__controls">
            <SeasonDropdown
              seasons={SEASONS}
              selected={selectedId}
              onSelect={setSelectedId}
            />

            <div className="browser__season-header">
              <div className="browser__season-title-row">
                <div>
                  <div className="section-label" style={{ marginBottom: '0.35rem' }}>
                    <span className="label-tag">Season Record</span>
                  </div>
                  <h2 className="headline headline-lg browser__season-title">
                    {activeSeason.game}{' '}
                    <span className="text-yellow">{activeSeason.year}</span>
                  </h2>
                  <p className="browser__season-sub text-muted">{activeSeason.sub}</p>
                </div>

                <div className="browser__season-meta">
                  {activeSeason.tag && (
                    <SeasonPill tag={activeSeason.tag} />
                  )}
                  {activeSeason.type === 'completed' && (
                    <span className="season-pill season-pill--completed">
                      Season Complete
                    </span>
                  )}
                </div>
              </div>

              <p className="browser__season-intro">{activeSeason.intro}</p>
            </div>
          </div>

          {/* ── Season Content (swaps on selection) ── */}
          <div className="browser__panel" key={selectedId}>
            {activeSeason.type === 'completed' ? (
              <CompletedSeason season={activeSeason} />
            ) : (
              <UpcomingSeason season={activeSeason} />
            )}
          </div>

        </div>
      </section>

    </main>
  );
}
